        <>
          <PrimaryButton onClick={() => setSession({ ...session, shown: true })}>Show answer</PrimaryButton>
          <p className="mt-3 hidden text-center text-[0.8125rem] text-muted-foreground min-[700px]:block">Space shows the answer.</p>
        </>
      )}
    </div>
  )
}

